import{at as e,it as t,o as n,vt as r}from"./chunks/framework.DQt_9H6f.js";var i=JSON.parse(`{"title":"First run","description":"","frontmatter":{},"headers":[],"relativePath":"guide/first-run.md","filePath":"guide/first-run.md"}`),a={name:`guide/first-run.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="first-run" tabindex="-1">First run <a class="header-anchor" href="#first-run" aria-label="Permalink to “First run”">​</a></h1><p>This walkthrough runs your first task, a polish of a <code>.tex</code> file, and shows how to inspect what changed in VS Code or the terminal. It takes under five minutes.</p><p>If you don&#39;t have TeXRA yet, read the <a href="./installation.html">installation guide</a>.</p><div class="tip custom-block"><p class="custom-block-title">Fresh install?</p><p>On a fresh install, the setup assistant offers to run this flow conversationally: it checks your environment, asks what you&#39;re working on, and runs the same polish demo, ending at the diff. Start it any time with <strong>TeXRA: Run Setup Assistant</strong> from the Command Palette in VS Code, or <code>texra setup</code> in the terminal. This page is the manual mirror of that conversation.</p></div><h2 id="step-0-add-a-key-or-connect-a-subscription" tabindex="-1">Step 0: add a key or connect a subscription <a class="header-anchor" href="#step-0-add-a-key-or-connect-a-subscription" aria-label="Permalink to “Step 0: add a key or connect a subscription”">​</a></h2><p>A credential is the one step no agent can do for you. Two ways in:</p><ul><li><strong>Use your own provider API key</strong>: Anthropic, OpenAI, Google, and more. Read <a href="./quick-start.html#add-a-key-or-connect-a-subscription">Quick start: add a key or connect a subscription</a>.</li><li><strong>Use a ChatGPT subscription</strong>: OpenAI models through your ChatGPT plan. In VS Code, open <strong>Settings → Models → Subscriptions</strong> and use the ChatGPT sign-in section; in the terminal, run <code>texra auth chatgpt login</code>. Grok connects from the same place; Kimi Code and the GLM Coding Plan take a key under <strong>Settings → Models → API keys</strong>.</li></ul><h2 id="get-a-sample-file" tabindex="-1">Get a sample file <a class="header-anchor" href="#get-a-sample-file" aria-label="Permalink to “Get a sample file”">​</a></h2><p>If you already have a working draft, skip this step. Otherwise:</p><h3 id="in-vs-code" tabindex="-1">In VS Code <a class="header-anchor" href="#in-vs-code" aria-label="Permalink to “In VS Code”">​</a></h3><p>Open the Command Palette (<code>Ctrl+Shift+P</code> / <code>Cmd+Shift+P</code>) and run <strong><code>TeXRA: Create Sample Project</code></strong>. This creates a ready-to-run workspace at <code>texra-sample/draft.tex</code>.</p><h3 id="in-the-terminal" tabindex="-1">In the terminal <a class="header-anchor" href="#in-the-terminal" aria-label="Permalink to “In the terminal”">​</a></h3><p>Any <code>.tex</code> file works. If you want a quick test file:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> draft.tex</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\documentclass{article}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\begin{document}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">The proposed method achieves significant improvements over the baseline,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">which is something that is very important for the field, and we will</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">demonstrate this in the following sections through various experiments.</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\end{document}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span></code></pre></div><h2 id="run-a-polish" tabindex="-1">Run a polish <a class="header-anchor" href="#run-a-polish" aria-label="Permalink to “Run a polish”">​</a></h2><h3 id="in-vs-code-1" tabindex="-1">In VS Code <a class="header-anchor" href="#in-vs-code-1" aria-label="Permalink to “In VS Code”">​</a></h3><ol><li>Open the folder that holds <code>draft.tex</code>.</li><li>Select the TeXRA icon in the Secondary Side Bar.</li><li>Pick <strong>Sonnet 5.5</strong> (<code>anthropic/claude-sonnet-5-5</code>) from the <strong>Model</strong> menu (or any available model).</li><li>Type an instruction that names the file: <blockquote><p>Polish draft.tex: tighten the prose. Preserve all math and citations.</p></blockquote></li><li>Select <strong>Start task</strong> (the arrow button).</li></ol><p>The Tasks view opens and streams the run. The assistant reads <code>draft.tex</code>, edits it in place and compiles it; each edit asks for your approval with a preview of the change. When it finishes, review the file in the editor or with <code>git diff</code>.</p><h3 id="in-the-terminal-1" tabindex="-1">In the terminal <a class="header-anchor" href="#in-the-terminal-1" aria-label="Permalink to “In the terminal”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">texra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --instruction</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Polish draft.tex: tighten the prose. Preserve all math and citations.&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --print</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> draft.tex</span></span></code></pre></div><h2 id="what-just-happened" tabindex="-1">What just happened <a class="header-anchor" href="#what-just-happened" aria-label="Permalink to “What just happened”">​</a></h2><p>The assistant worked as a person would: it read the file, made its edits with its file tools, and compiled the result. For a job with a check that must hold, such as a referee&#39;s comments that leave the text alone, it starts a <a href="./programs.html">program</a>:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">texra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> annotate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> draft.tex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --instruction</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Read as a first-time reader&quot;</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><ul><li><a href="./workflows/polish-a-draft.html"><strong>Polish a draft</strong></a>: how to ask for a careful polish</li><li><a href="./programs.html"><strong>The assistant and programs</strong></a>: what you can ask for, and every program you can start</li><li><a href="./models.html"><strong>Models</strong></a>: choosing a model that matches the work</li><li><a href="./texra-cli.html"><strong>TeXRA CLI</strong></a>: sign-in, project defaults, headless output formats</li><li><a href="./latex-diff.html"><strong>LaTeX Diff</strong></a>: a marked-up PDF of what changed</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};